import AppKit

struct FillPreview {var pattern:Pattern;var defaults:[Int];var hits:Int;var random:Bool}

extension Tracker {
    func fillTargets()->(ClosedRange<Int>,ClosedRange<Int>){if anchor != nil{return selection};return(track...track,0...(pattern.length-1))}
    func fillInstrument(_ t:Int)->Int{if fillSettings.instrument>=0{return fillSettings.instrument};let assigned=trackDefaults[t];if assigned>=0&&slots[assigned].name != "EMPTY"{return assigned};let suggested=fillRole.factory;if slots[suggested].name != "EMPTY"{return suggested};if let i=slots.firstIndex(where:{$0.wave==suggested&&$0.name != "EMPTY"}){return i};return slots.firstIndex(where:{$0.name != "EMPTY"}) ?? 0}
    func fillDefaultNote(){let slot=slots[fillInstrument(track)];fillSettings.drumNote=slot.pcm != nil ? slot.root:fillRole.drumNote}
    func fill(){guard !addTrackSelected,requireRec() else{return};fillFocus=0;fillPreset=0;fillSettingRow=0;fillSettings=FillSettings(root:project.fillRoot ?? 0,scale:project.fillScale ?? 1,octave:fillRole.octave,harmony:project.fillHarmony ?? 0,fxAmount:project.fillFXAmount ?? 50,sustain:project.fillSustain ?? 65);fillDefaultNote();fillPreview=nil;modal=5;needsDisplay=true}
    func discardFillPreview(){if fillPreview != nil{let target=fillTargets(),p=pattern;for t in target.0{for r in target.1{push(project.selected,t,r,p.cells[t][r])}}};fillPreview=nil}
    func cancelFill(){discardFillPreview();modal=0;message="Fill cancelled";needsDisplay=true}
    func fillContext(excluding:ClosedRange<Int>)->[Int:FillHarmony]{var context=[Int:FillHarmony](),chord:FillHarmony?,hint:FillHarmony?;let p=pattern;for r in 0..<p.length{for t in 0..<24 where !excluding.contains(t){let c=p.cells[t][r];if c.notes.count>=3{chord=FillHarmony(root:c.harmonicRoot ?? c.notes[0],notes:c.notes);break}};for t in 0..<24 where !excluding.contains(t){let c=p.cells[t][r];if let root=c.harmonicRoot,!c.notes.isEmpty{hint=FillHarmony(root:root,notes:c.notes);break}};if let h=chord ?? hint{context[r]=h}};return context}
    func generateFill(random:Bool){let targets=fillTargets(),old=fillPreview?.pattern ?? pattern,preset=random ? fillRole.presets.count-1:fillPreset;let context=fillRole.melodic ? fillContext(excluding:targets.0):[:];var result=pattern,defaults=trackDefaults,total=0;var system=SystemRandomNumberGenerator()
        for t in targets.0{let ins=fillInstrument(t);if slots[ins].name=="EMPTY"{continue};if defaults[t]<0{defaults[t]=ins};var settings=fillSettings;if !fillRole.melodic&&settings.instrument<0&&slots[ins].pcm != nil&&t != track{settings.drumNote=slots[ins].root};var generated=[Cell]();for _ in 0..<8{var gen=CreativeFill(role:fillRole,preset:preset,options:settings,instrument:ins,start:targets.1.lowerBound,count:targets.1.count,context:context,rng:FillRNG(state:system.next()));generated=gen.generate();if !random||Array(old.cells[t][targets.1]) != generated{break}};if random&&Array(old.cells[t][targets.1])==generated,let i=generated.firstIndex(where:{!$0.notes.isEmpty}){let v=generated[i].velocity ?? 80;generated[i].velocity=v==100 ? 99:v+1};for (i,r) in targets.1.enumerated(){if settings.replace || result.cells[t][r].notes.isEmpty{result.cells[t][r]=generated[i];if !generated[i].notes.isEmpty{total+=1}}}}
        fillPreview=FillPreview(pattern:result,defaults:defaults,hits:total,random:random||preset==fillRole.presets.count-1);for t in targets.0{for r in targets.1{push(project.selected,t,r,result.cells[t][r])}};message="Preview: \(total) events";needsDisplay=true
    }
    func applyFill(){if fillPreview==nil{generateFill(random:false)};guard let candidate=fillPreview else{return};checkpoint();project.fillFXAmount=fillSettings.fxAmount;project.fillSustain=fillSettings.sustain;var p=candidate.pattern;p.trackInstruments=candidate.defaults;pattern=p;if fillRole.melodic{project.fillRoot=fillSettings.root;project.fillScale=fillSettings.scale;project.fillHarmony=fillSettings.harmony};fillPreview=nil;modal=0;anchor=nil;sync();message="Filled \(candidate.hits) events · \(fillRole.title)";needsDisplay=true}
    func fillSettingsRows()->[(String,String)]{let ins=fillInstrument(track);var rows:[(String,String)]=[("Instrument",fillSettings.instrument<0 ? "Auto · \(slots[ins].name)":"\(ins+1) \(slots[ins].name)")];if fillRole.melodic{rows += [("Root",names[fillSettings.root]),("Scale",fillScales[fillSettings.scale].name),("Octave","\(fillSettings.octave)"),("Harmony",CreativeFill.harmonies[fillSettings.harmony])]}else{rows += [("Note",noteName(fillSettings.drumNote))]};rows += [("Density","\(fillSettings.density)%"),("Swing","\(fillSettings.swing)%"),("Humanize","\(fillSettings.humanize)%"),("FX Amount","\(fillSettings.fxAmount)%"),("Sustain","\(fillSettings.sustain)%"),("Mode",fillSettings.replace ? "Replace":"Empty only")];return rows}
    func selectFillRole(_ d:Int){discardFillPreview();fillRole=FillRole(rawValue:(fillRole.rawValue+d+6)%6)!;fillPreset=0;fillSettings.octave=fillRole.octave;fillSettingRow=0;fillDefaultNote()}
    func adjustFillSetting(_ d:Int){discardFillPreview();let key=fillSettingsRows()[fillSettingRow].0;let sign=d>0 ? 1:-1;switch key{case "Instrument":let available=[-1]+slots.indices.filter{slots[$0].name != "EMPTY"};let i=available.firstIndex(of:fillSettings.instrument) ?? 0;fillSettings.instrument=available[(i+sign+available.count)%available.count];fillDefaultNote();case "Root":fillSettings.root=(fillSettings.root+sign+12)%12;case "Scale":fillSettings.scale=(fillSettings.scale+sign+fillScales.count)%fillScales.count;case "Octave":fillSettings.octave=max(0,min(6,fillSettings.octave+sign));case "Harmony":fillSettings.harmony=(fillSettings.harmony+sign+CreativeFill.harmonies.count)%CreativeFill.harmonies.count;case "Note":fillSettings.drumNote=max(0,min(127,fillSettings.drumNote+d));case "Density":fillSettings.density=max(0,min(100,fillSettings.density+sign*(abs(d)>1 ? 10:5)));case "Swing":fillSettings.swing=max(0,min(50,fillSettings.swing+sign*(abs(d)>1 ? 10:5)));case "Humanize":fillSettings.humanize=max(0,min(100,fillSettings.humanize+sign*(abs(d)>1 ? 10:5)));case "FX Amount":fillSettings.fxAmount=max(0,min(100,fillSettings.fxAmount+sign*(abs(d)>1 ? 10:5)));case "Sustain":fillSettings.sustain=max(0,min(100,fillSettings.sustain+sign*(abs(d)>1 ? 10:5)));default:fillSettings.replace.toggle()}}
    func fillKey(_ event:NSEvent){let code=event.keyCode,ch=event.charactersIgnoringModifiers?.lowercased() ?? "",shift=event.modifierFlags.contains(.shift);if event.modifierFlags.contains(.command){if code==22{generateFill(random:false)}else if code==26{fillPreset=fillRole.presets.count-1;generateFill(random:true)}else if code==28{applyFill()};return};switch code{case 53:cancelFill();case 36,76,100:applyFill();case 97:generateFill(random:false);case 98:fillPreset=fillRole.presets.count-1;generateFill(random:true);case 49:togglePlay();case 48:fillFocus=(fillFocus+1)%3;case 123:fillFocus=max(0,fillFocus-1);case 124:fillFocus=min(2,fillFocus+1);case 125,126:let d=code==125 ? 1:-1;if fillFocus==0{selectFillRole(d)}else if fillFocus==1{discardFillPreview();fillPreset=(fillPreset+d+fillRole.presets.count)%fillRole.presets.count}else{fillSettingRow=max(0,min(fillSettingsRows().count-1,fillSettingRow+d))};default:if ch=="r"{fillPreset=fillRole.presets.count-1;generateFill(random:true)}else if ch=="p"{generateFill(random:false)}else if ch=="q"||ch=="e"{let d=(ch=="e" ? 1:-1)*(shift ? 10:1);if fillFocus==2{adjustFillSetting(d)}else if fillFocus==0{selectFillRole(d>0 ? 1:-1)}else{discardFillPreview();let n=fillRole.presets.count;fillPreset=(fillPreset+(d>0 ? 1:-1)+n)%n}}};needsDisplay=true}
    func fillBox()->NSRect{let bw=min(900,bounds.width-40),bh=min(560,bounds.height-48);return NSRect(x:(bounds.width-bw)/2,y:(bounds.height-bh)/2,width:bw,height:bh)}
    func drawFill(){let box=fillBox(),x=box.minX,y=box.minY,bw=box.width,bh=box.height;rect(0,0,bounds.width,bounds.height,NSColor.black.withAlphaComponent(0.57));rect(x,y,bw,bh,gray(0.17));border(x,y,bw,bh,gray(0.65));rect(x,y,bw,40,gray(0.25));txt("CREATIVE FILL",x+16,y+12,12,teal,true);let ranges=fillTargets();let tr=ranges.0.count==1 ? "Track \(ranges.0.lowerBound+1)":"Tracks \(ranges.0.lowerBound+1)–\(ranges.0.upperBound+1)";txt("\(tr)  ·  Steps \(ranges.1.lowerBound+1)–\(ranges.1.upperBound+1)",x+bw*0.45,y+12,12,gray(0.70))
        let a=bw*0.20,b=bw*0.34,c=bw-a-b,top=y+54;let cols=[(x,a,"CATEGORY"),(x+a,b,"PRESET"),(x+a+b,c,"PARAMETERS")];for (i,col) in cols.enumerated(){rect(col.0+4,top,col.1-8,304,gray(0.13));border(col.0+4,top,col.1-8,304,i==fillFocus ? teal:gray(0.31));txt(col.2,col.0+13,top+8,12,i==fillFocus ? teal:gray(0.63),true)}
        for role in FillRole.allCases{let yy=top+35+CGFloat(role.rawValue)*27;if role==fillRole{rect(x+9,yy,a-18,25,gray(0.32))};txt(role.title,x+16,yy+5,12,role==fillRole ? teal:gray(0.8),role==fillRole)}
        for (i,preset) in fillRole.presets.enumerated(){let yy=top+35+CGFloat(i)*27;if i==fillPreset{rect(x+a+9,yy,b-18,25,gray(0.32))};txt(preset,x+a+16,yy+5,12,i==fillPreset ? teal:gray(0.8),i==fillPreset)}
        for (i,pair) in fillSettingsRows().enumerated(){let yy=top+35+CGFloat(i)*24;if fillFocus==2&&i==fillSettingRow{rect(x+a+b+9,yy,c-18,22,gray(0.32))};txt(pair.0,x+a+b+15,yy+5,12,gray(0.7));txt(String(pair.1.prefix(28)),x+a+b+c*0.36,yy+5,12,i==fillSettingRow&&fillFocus==2 ? teal:terminText,true)}
        let py=top+316;txt(fillPreview==nil ? "PREVIEW · Generate to hear the pattern":"PREVIEW · \(fillPreview!.hits) events · \(fillPreview!.random ? "Random":"Preset")",x+15,py,12,teal,true);let lane=fillPreview?.pattern.cells[track],stepStart=ranges.1.lowerBound,count=min(32,ranges.1.count),cellW=(bw-30)/CGFloat(max(1,count));for i in 0..<count{let xx=x+15+CGFloat(i)*cellW,yy=py+24,cell=lane?[stepStart+i];rect(xx,yy,cellW-2,45,gray(i%4==0 ? 0.26:0.20));if let v=cell,!v.notes.isEmpty{let vh=CGFloat(v.velocity ?? 80)*0.35;rect(xx+2,yy+43-vh,max(1,cellW-6),vh,teal);if [2,4,5,6,8].contains(v.fx ?? 0)||[2,4,5,6,8].contains(v.fx2 ?? 0){rect(xx+2,yy+2,max(1,cellW-6),3,purple)}}};let fy=y+bh-57;let buttons=[("ESC  Cancel",gray(0.25)),("F6  Preview",gray(0.25)),("F7  RANDOM",purple),("F8  APPLY",teal)];let fw=(bw-20)/4;for i in 0..<4{let xx=x+10+CGFloat(i)*fw;rect(xx,fy,fw-5,30,buttons[i].1);centered(buttons[i].0,xx,fy+7,fw-5,12,i>1 ? .black:terminText,true)};centered("← → Column   ↑ ↓ Select   Q/E Change   SPACE Listen   R Re-roll   ENTER Apply",x,y+bh-21,bw,11,gray(0.75))
    }
    func fillMouse(_ p:NSPoint){let box=fillBox(),x=box.minX,y=box.minY,a=box.width*0.20,b=box.width*0.34,top=y+54;if p.y>=y+box.height-57&&p.y<y+box.height-27&&p.x>=x&&p.x<=box.maxX{let i=min(3,max(0,Int((p.x-x-10)/((box.width-20)/4))));switch i{case 0:cancelFill();case 1:generateFill(random:false);case 2:fillPreset=fillRole.presets.count-1;generateFill(random:true);default:applyFill()};return};if p.y>=top+35&&p.y<top+304{let row=Int((p.y-top-35)/27);if p.x>x&&p.x<x+a&&row<6{selectFillRole(row-fillRole.rawValue);fillFocus=0}else if p.x>=x+a&&p.x<x+a+b&&row<fillRole.presets.count{discardFillPreview();fillPreset=row;fillFocus=1}else if p.x>=x+a+b&&p.x<box.maxX{let param=Int((p.y-top-35)/24);if param<fillSettingsRows().count{fillSettingRow=param;fillFocus=2}}};needsDisplay=true}
}
